    next: /^next(?:\s+([a-z_]\w*))?$/i,
    whileLoop: /^while\s+(.+?)(?:\s+do)?$/i,
    endWhile: /^end\s*while$/i,
    ifThen: /^if\s+(.+?)\s+then(?:\s+(.*))?$/i,
    elseLine: /^else(?:\s+(.*))?$/i,
    endIf: /^end\s*if$/i,
    input: /^input\s+(.+)$/i,
    output: /^output\s+(.+)$/i,
    end: /^end$/i,
    assign: /^([a-z_]\w*)\s*=(?!=)\s*(.+)$/i
